fn find_unfinished(directory: &Path, process: &str) -> Option<Unfinished> {
    use std::collections::BTreeMap;
    // One entry per run, (start, pid), holding its highest part.
    let mut runs: BTreeMap<(String, u32), (u32, PathBuf)> = BTreeMap::new();
    for entry in std::fs::read_dir(directory).ok()?.flatten() {
        let name = entry.file_name().to_string_lossy().into_owned();
        let Some((owner, started, pid, part)) = parse_name(&name) else {
            continue;
        };
        if owner != process {
            continue;
        }
        let run = runs.entry((started.to_owned(), pid)).or_default();
        if part >= run.0 {
            *run = (part, entry.path());
        }
    }
    for ((started, pid), (_, path)) in runs.into_iter().rev() {
        if held_by_a_writer(&path) {
            continue;
        }
        let last = last_record(&path);
        let event = last
            .as_ref()
            .and_then(|record| record["event"].as_str())
            .map(str::to_owned);
        if event.as_deref() == Some("log.stop") {
            return None;
        }
        return Some(Unfinished {
            file: path.file_name()?.to_string_lossy().into_owned(),
            started,
            pid,
            last_seq: last.as_ref().and_then(|record| record["seq"].as_u64()),
            last_ts: last
                .as_ref()
                .and_then(|record| record["ts"].as_str())
                .map(str::to_owned),
            last_event: event,
        });
    }
    None
}

/// Days since 1970-01-01 to a civil date (Howard Hinnant's algorithm).
fn civil(days: i64) -> (i64, u32, u32) {
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let month = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    let year = yoe + era * 400 + i64::from(month <= 2);
    (year, month, day)
}

fn parts(time: SystemTime) -> (i64, u32, u32, u64, u64, u64, u32) {
    let since = time.duration_since(UNIX_EPOCH).unwrap_or_default();
    let secs = since.as_secs();
    let (year, month, day) = civil((secs / 86_400) as i64);
    let rem = secs % 86_400;
    (
        year,
        month,
        day,
        rem / 3600,
        rem % 3600 / 60,
        rem % 60,
        since.subsec_micros(),
    )
}

